pub(crate) fn spawn_rigid_body_2d_component(
    entity: Entity,
    value: &Value,
    context: &mut SpawnContext<'_>,
) -> Result<(), ComponentSpawnError> {
    let component_type = ComponentTypeId::new(RIGID_BODY_2D_COMPONENT);
    const EXPECTED: &str = "a RigidBody2D object with mode, finite velocity, angular velocity, gravity scale, and continuous fields";
    let fields = ComponentFields::new(context.authoring_entity, &component_type, value, EXPECTED)?;
    let mode = match fields.string("mode")? {
        "fixed" => RigidBodyMode2d::Fixed,
        "dynamic" => RigidBodyMode2d::Dynamic,
        "kinematic" => RigidBodyMode2d::Kinematic,
        _ => return Err(fields.invalid(EXPECTED).into()),
    };
    let body = RigidBody2d {
        mode,
        velocity: [fields.f32("velocity_x")?, fields.f32("velocity_y")?],
        angular_velocity: fields.f32("angular_velocity")?,
        gravity_scale: fields.f32("gravity_scale")?,
        continuous: fields.bool("continuous")?,
    };
    if body.velocity.iter().any(|value| !value.is_finite())
        || !body.angular_velocity.is_finite()
        || !body.gravity_scale.is_finite()
        || body.gravity_scale < 0.0
    {
        return Err(fields.invalid(EXPECTED).into());
    }
    if let Some(existing) = context.world.get_component_mut::<RigidBody2d>(entity) {
        *existing = body;
    } else {
        context.world.add_component(entity, body)?;
    }
    Ok(())
}

pub(crate) fn spawn_collider_2d_component(
    entity: Entity,
    value: &Value,
    context: &mut SpawnContext<'_>,
) -> Result<(), ComponentSpawnError> {
    let component_type = ComponentTypeId::new(COLLIDER_2D_COMPONENT);
    const EXPECTED: &str = "a Collider2D object with valid geometry, material coefficients, filtering, sensor, and one-way fields";
    let fields = ComponentFields::new(context.authoring_entity, &component_type, value, EXPECTED)?;
    let shape = match fields.string("shape")? {
        "box" => ColliderShape2d::Box {
            half_extents: [fields.f32("half_extent_x")?, fields.f32("half_extent_y")?],
        },
        "circle" => ColliderShape2d::Circle {
            radius: fields.f32("radius")?,
        },
        "capsule" => ColliderShape2d::Capsule {
            half_height: fields.f32("half_height")?,
            radius: fields.f32("radius")?,
        },
        "polygon" => {
            let Some(Value::Array(values)) = fields.get("polygon_points") else {
                return Err(fields.invalid(EXPECTED).into());
            };
            if values.len() < 3 {
                return Err(fields.invalid("a polygon with at least three finite x/y points").into());
            }
            let mut points = Vec::with_capacity(values.len());
            for value in values {
                let Value::Object(point) = value else {
                    return Err(fields.invalid(EXPECTED).into());
                };
                let numeric = |name: &str| match point.get(name) {
                    Some(Value::F64(value)) => Some(*value as f32),
                    Some(Value::I64(value)) => Some(*value as f32),
                    Some(Value::U64(value)) => Some(*value as f32),
                    _ => None,
                };
                let x = numeric("x").filter(|value| value.is_finite())
                    .ok_or_else(|| fields.invalid(EXPECTED))?;
                let y = numeric("y").filter(|value| value.is_finite())
                    .ok_or_else(|| fields.invalid(EXPECTED))?;
                points.push([x, y]);
            }
            ColliderShape2d::Polygon { points }
        }
        _ => return Err(fields.invalid(EXPECTED).into()),
    };
    let membership = u32::try_from(fields.i64("membership")?)
        .map_err(|_| fields.invalid(EXPECTED))?;
    let mask = u32::try_from(fields.i64("mask")?)
        .map_err(|_| fields.invalid(EXPECTED))?;
    let friction = fields.f32("friction")?;
    let restitution = fields.f32("restitution")?;
    let geometry_valid = match &shape {
        ColliderShape2d::Box { half_extents } => half_extents.iter().all(|value| value.is_finite() && *value > 0.0),
        ColliderShape2d::Circle { radius } => radius.is_finite() && *radius > 0.0,
        ColliderShape2d::Capsule { half_height, radius } => half_height.is_finite() && *half_height >= 0.0 && radius.is_finite() && *radius > 0.0,
        ColliderShape2d::Polygon { points } => points.len() >= 3 && points.iter().flatten().all(|value| value.is_finite()),
    };
    if !geometry_valid
        || !friction.is_finite()
        || friction < 0.0
        || !restitution.is_finite()
        || !(0.0..=1.0).contains(&restitution)
    {
        return Err(fields.invalid(EXPECTED).into());
    }
    context.world.add_component(
        entity,
        Collider2d {
            shape,
            sensor: fields.bool("sensor")?,
            friction,
            restitution,
            filter: CollisionFilter2d { memberships: membership, mask },
            one_way: fields.bool("one_way")?,
        },
    )?;
    if context.world.get_component::<RigidBody2d>(entity).is_none() {
        context.world.add_component(
            entity,
            RigidBody2d {
                mode: RigidBodyMode2d::Fixed,
                velocity: [0.0, 0.0],
                angular_velocity: 0.0,
                gravity_scale: 0.0,
                continuous: false,
            },
        )?;
    }
    Ok(())
}

